True from collections import Counter

def transform(grid):
    """Move the non-background object up against the full 2-line; mark its far edge with 8."""
    a=[list(row) for row in grid]
    h,w=len(a),len(a[0])
    line=None
    for r,row in enumerate(a):
        if all(v==2 for v in row):
            line=(0,r); break
    if line is None:
        for c in range(w):
            if all(a[r][c]==2 for r in range(h)):
                line=(1,c); break
    if line is None:
        return a
    axis,d=line
    counts=Counter(v for row in a for v in row if v!=2)
    if not counts:
        return a
    bg=counts.most_common(1)[0][0]
    colors=[v for v in counts if v!=bg]
    if not colors:
        return a
    # The task's movable pattern is the non-background, non-divider color.
    color=max(colors,key=lambda v:counts[v])
    pts=[(r,c) for r in range(h) for c in range(w) if a[r][c]==color]
    if not pts:
        return a
    coords=[r if axis==0 else c for r,c in pts]
    lo,hi=min(coords),max(coords)
    before=(sum(coords)/len(coords) < d)
    if before:
        delta=(d-1)-hi
    else:
        delta=(d+1)-lo
    out=[row[:] for row in a]
    # Clear the old pattern, then translate all of its colored cells toward the 2-line.
    for r,c in pts:
        out[r][c]=bg
    moved=[]
    for r,c in pts:
        nr,nc=(r+delta,c) if axis==0 else (r,c+delta)
        if 0<=nr<h and 0<=nc<w:
            out[nr][nc]=color
            moved.append((nr,nc))
    if moved:
        moved_coords=[r if axis==0 else c for r,c in moved]
        marker=(min(moved_coords)-1) if before else (max(moved_coords)+1)
        if 0<=marker<(h if axis==0 else w):
            if axis==0:
                out[marker]=[8]*w
            else:
                for r in range(h): out[r][marker]=8
    return out
